const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const selectedHook = String($json.selected_hook ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Publish Draft Item did not produce a valid content_id.');
}
if (!title) {
  throw new Error('Fetch Next Publish Draft Item did not produce a title.');
}
if (!selectedHook) {
  throw new Error('Fetch Next Publish Draft Item did not produce a selected_hook.');
}
const narrationScript = String($json.narration_script ?? '').trim();
if (!narrationScript) {
  throw new Error('Fetch Next Publish Draft Item did not produce a narration_script.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    selected_hook: selectedHook,
    narration_script: narrationScript,
    caption_draft: String($json.caption_draft ?? '').trim(),
    cta_line: String($json.cta_line ?? '').trim(),
    publish_status_after_success: 'draft',
    workflow_name: 'wf_caption_and_hashtags',
    run_started_at: new Date().toISOString()
  }
}];

const title = String($json.title ?? '').trim();
const captionDraft = String($json.caption_draft ?? '').trim();
const ctaLine = String($json.cta_line ?? '').trim();
const selectedHook = String($json.selected_hook ?? '').trim();
const category = String($json.category ?? 'general').trim().toLowerCase();

// Build final caption directly from research-generated fields — no LLM needed
const captionParts = [];
if (captionDraft) captionParts.push(captionDraft);
if (ctaLine) captionParts.push(ctaLine);
const captionFinal = captionParts.join('\n\n') || selectedHook || title;

// Category-aware hashtag sets
const HASHTAG_MAP = {
  history: '#history #historical #worldhistory #historyfacts #ancienthistory #truestory',
  mystery: '#mystery #unsolved #truemystery #unexplained #creepy #truecrime',
  'true crime': '#truecrime #crimestory #coldcase #truecrimeaddict #crimepodcast #realstory',
  crime: '#crime #truecrime #crimestory #coldcase #realstory #truestory',
  war: '#war #military #history #warhistory #historicalfacts #truestory',
  culture: '#culture #history #worldhistory #traditions #heritage #truestory',
  science: '#science #facts #historicalfacts #discovery #truestory #educational',
};
const matchedKey = Object.keys(HASHTAG_MAP).find((k) => category.includes(k)) ?? null;
const hashtagsFinal = matchedKey ? HASHTAG_MAP[matchedKey] : '#history #truestory #realstory #historical #factsonly #storytelling';

return [{
  json: {
    content_id: $json.content_id,
    workflow_name: $json.workflow_name,
    run_started_at: $json.run_started_at,
    publish_status_after_success: $json.publish_status_after_success,
    caption_final: captionFinal,
    hashtags_final: hashtagsFinal,
    selection_rationale: 'Assembled directly from research caption_draft and cta_line without LLM call',
    generation_model: '',
    cost: { type: 'none', provider: 'none', total_usd: 0 },
    caption_iteration_json: {
      provider: 'none',
      assembled_from_draft: true,
      output: {
        caption_final: captionFinal,
        hashtags_final: hashtagsFinal
      }
    }
  }
}];

const cost_json_sql = JSON.stringify($json.cost ?? {}).replaceAll("'", "''");
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Prepare Publish Draft SQL Values received an invalid content_id: ' + (contentId || '<empty>') + '.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    caption_final_sql: String($json.caption_final ?? '').replaceAll("'", "''"),
    hashtags_final_sql: String($json.hashtags_final ?? '').replaceAll("'", "''"),
    publish_status_sql: String($json.publish_status_after_success ?? 'draft').replaceAll("'", "''"),
    workflow_name_sql: String($json.workflow_name ?? 'wf_caption_and_hashtags').replaceAll("'", "''"),
    generation_model_sql: String($json.generation_model ?? '').replaceAll("'", "''"),
    selection_rationale_sql: String($json.selection_rationale ?? '').replaceAll("'", "''"),
    caption_iteration_json_sql: JSON.stringify($json.caption_iteration_json ?? {}).replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0,
    cost_json_sql
  }
}];
